import type { IncomingMessage, ServerResponse } from 'node:http';
import {
  INSIGHT_FRICTION,
  INSIGHT_FUNNELS,
  INSIGHT_PATHS,
  INSIGHT_PERFORMANCE,
  INSIGHT_RELEASES,
} from '@/test/fixtures/insight-shapes';

// The insight routes of the stand-in back end, for the browser tests (W9F). The answers are the JSON the
// real back end's mappers write (test/fixtures/insight-shapes.ts, generated by insight-shapes.gen.py).
// The events the browser sends are counted nowhere here: the stand-in only says it took them.

const TABS: Record<string, unknown> = {
  funnels: INSIGHT_FUNNELS,
  paths: INSIGHT_PATHS,
  friction: INSIGHT_FRICTION,
  performance: INSIGHT_PERFORMANCE,
  releases: INSIGHT_RELEASES,
};

function send(response: ServerResponse, status: number, body: unknown) {
  response.writeHead(status, { 'Content-Type': 'application/json', 'Cache-Control': 'no-store' }).end(JSON.stringify(body));
}

function drain(request: IncomingMessage): Promise<void> {
  return new Promise((resolve) => {
    request.on('data', () => undefined);
    request.on('end', () => resolve());
  });
}

/** Answers `GET /support/insight/{tab}` and `POST /telemetry/ui`; false for any other path. */
export async function handleInsightRoute(request: IncomingMessage, response: ServerResponse, pathname: string): Promise<boolean> {
  if (request.method === 'POST' && pathname === '/telemetry/ui') {
    await drain(request);
    send(response, 200, { accepted: 0, dropped: 0 });
    return true;
  }
  const tab = /^\/support\/insight\/([a-z]+)$/.exec(pathname)?.[1];
  if (request.method !== 'GET' || tab === undefined) return false;
  const answer = TABS[tab];
  if (answer === undefined) send(response, 400, { resourceType: 'OperationOutcome', issue: [{ severity: 'error', code: 'invalid' }] });
  else send(response, 200, answer);
  return true;
}
